local function install()
    if not ScriptManager or not ModelAttachment then return end
    for _,s in ipairs(sockets) do
        local body=ScriptManager.instance:getModelScript(s.body)
        if body and not body:getAttachmentById(s.name) then
            local a=ModelAttachment.new(s.name)
            a:setBone(s.bone)
            a:getOffset():set(s.offset[1],s.offset[2],s.offset[3])
            a:getRotate():set(s.rotate[1],s.rotate[2],s.rotate[3])
            body:addAttachment(a)
        end
    end
end
if Events.OnGameBoot then Events.OnGameBoot.Add(install) end
if Events.OnGameStart then Events.OnGameStart.Add(install) end
if Events.OnServerStarted then Events.OnServerStarted.Add(install) end
